{
  "name": "@openlines/nmnm-opencode",
  "version": "0.3.2",
  "description": "OpenCode adapter for nanomneme local SQLite memory",
  "type": "module",
  "keywords": [
    "opencode",
    "plugin",
    "coding-agent",
    "memory",
    "adapter"
  ],
  "main": "./index.js",
  "exports": {
    ".": {
      "import": "./index.js"
    },
    "./server": {
      "import": "./index.js"
    },
    "./tui": {
      "import": "./tui.js"
    }
  },
  "files": [
    "index.js",
    "tui.js",
    "bin",
    "src",
    "docs/OPENCODE_ADAPTER_MANUAL.md",
    "docs/img",
    "README.md",
    "LICENSE"
  ],
  "bin": {
    "nmnm-opencode": "./bin/memory.js"
  },
  "dependencies": {
    "@opencode-ai/plugin": ">=1.18.15",
    "jsonc-parser": "3.3.1",
    "@openlines/nmnm-core": "^0.3.2"
  },
  "engines": {
    "node": ">=22.13.0"
  },
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "author": "Linel Lazatin",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/linellazatin/nanomneme.git",
    "directory": "adapters/opencode"
  }
}
